var Q6 = [
{n:1, q:'La organización territorial del Estado se regula en la Constitución Española en:', o:{a:'El Título VII.',b:'El Título VIII.',c:'El Título IX.',d:'El Título VI.'}, correct:'d', why:{d:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:2, q:'Según la Constitución, el territorio del Estado está organizado en:', o:{a:'Municipios, provincias y Comunidades Autónomas.',b:'Solo municipios y provincias.',c:'Municipios, comarcas y regiones.',d:'Provincias y Comunidades Autónomas.'}, correct:'c', why:{c:'El art.137 CE establece que el Estado se organiza territorialmente en municipios, en provincias y en las Comunidades Autónomas que se constituyan.'}},
{n:3, q:'Según la CE, todos los entes territoriales gozan de autonomía para la gestión de sus respectivos intereses. Este principio se denomina:', o:{a:'Principio de descentralización.',b:'Principio de autonomía territorial.',c:'Principio de subsidiariedad.',d:'Principio de coordinación.'}, correct:'c', why:{c:'El art.137 CE reconoce que los municipios, provincias y CCAA gozan de autonomía para la gestión de sus respectivos intereses, que es el principio de autonomía territorial reconocido constitucionalmente.'}},
{n:4, q:'La Constitución garantiza la autonomía de los municipios. Los municipios tienen personalidad jurídica plena y su gobierno y administración corresponde a sus respectivos:', o:{a:'Alcaldes.',b:'Ayuntamientos.',c:'Diputaciones.',d:'Concejos.'}, correct:'c', why:{c:'El art.140 CE establece que la Constitución garantiza la autonomía de los municipios, que tendrán personalidad jurídica plena. Su gobierno y administración corresponde a sus respectivos Ayuntamientos.'}},
{n:5, q:'Según la CE, los Ayuntamientos están integrados por:', o:{a:'El Alcalde y los Concejales.',b:'El Alcalde, los Concejales y la Junta de Gobierno.',c:'Solo los Concejales.',d:'El Alcalde, los Tenientes de Alcalde y los Concejales.'}, correct:'c', why:{c:'El art.140 CE establece que los Ayuntamientos están integrados por los Concejales y el Alcalde.'}},
{n:6, q:'Los Concejales son elegidos por:', o:{a:'Los vecinos del municipio mediante sufragio universal.',b:'El Pleno del Ayuntamiento.',c:'El Gobernador Civil.',d:'La Diputación Provincial.'}, correct:'d', why:{d:'El art.140 CE establece que los Concejales serán elegidos por los vecinos del municipio mediante sufragio universal, igual, libre, directo y secreto.'}},
{n:7, q:'El Alcalde es elegido por:', o:{a:'Los vecinos directamente.',b:'Los Concejales o por los vecinos, en los términos que determine la ley.',c:'El Gobierno de la Nación.',d:'El Presidente de la Comunidad Autónoma.'}, correct:'a', why:{a:'El art.140 CE establece que el Alcalde será elegido por los Concejales o por los vecinos, en los términos que la ley determine.'}},
{n:8, q:'La provincia es una entidad local con personalidad jurídica propia, determinada por la agrupación de municipios y división territorial para el cumplimiento de las actividades del Estado. Su gobierno y administración autónoma corresponde a:', o:{a:'El Gobernador Civil.',b:'La Diputación Provincial u otras Corporaciones de carácter representativo.',c:'El Gobierno de la CCAA.',d:'El Delegado del Gobierno.'}, correct:'c', why:{c:'El art.141.2 CE establece que el gobierno y la administración autónoma de las provincias estarán encomendados a Diputaciones u otras Corporaciones de carácter representativo.'}},
{n:9, q:'¿Cuántas provincias tiene España?', o:{a:'47.',b:'50.',c:'52.',d:'48.'}, correct:'a', why:{a:'España tiene 50 provincias, conforme a la organización territorial histórica consolidada en la Ley de 30 de noviembre de 1833.'}},
{n:10, q:'La creación, supresión y alteración de los límites de las provincias:', o:{a:'Corresponde al Gobierno.',b:'Corresponde a las Cortes Generales mediante ley orgánica.',c:'Corresponde a las CCAA afectadas.',d:'Corresponde al Senado.'}, correct:'a', why:{a:'El art.141.1 CE establece que cualquier alteración de los límites provinciales habrá de ser aprobada por las Cortes Generales mediante ley orgánica.'}},
{n:11, q:'La creación de agrupaciones de municipios diferentes de la provincia necesita:', o:{a:'Autorización de la Diputación Provincial.',b:'Ley de la Comunidad Autónoma.',c:'Ley estatal.',d:'Decreto del Gobierno.'}, correct:'d', why:{d:'El art.141.3 CE establece que se podrán crear agrupaciones de municipios diferentes de la provincia. En las CCAA uniprovinciales y en los territorios insulares esta administración la ejerce la propia CCAA.'}},
{n:12, q:'La Ley de Bases del Régimen Local actualmente vigente es:', o:{a:'Ley 7/1985, de 2 de abril.',b:'Ley 30/1992, de 26 de noviembre.',c:'Ley 11/1999, de 21 de abril.',d:'Ley 57/2003, de 16 de diciembre.'}, correct:'b', why:{b:'La Ley 7/1985, de 2 de abril, reguladora de las Bases del Régimen Local (LBRL) es la ley básica que regula la organización y funcionamiento de los municipios y provincias españoles.'}},
{n:13, q:'Según la LBRL, el municipio es la entidad local básica de la organización territorial del Estado. El municipio tiene personalidad jurídica y plena capacidad para el cumplimiento de sus fines. Sus elementos son:', o:{a:'El territorio, la población y la organización.',b:'El Ayuntamiento, la población y el término municipal.',c:'Solo el territorio y la población.',d:'El término municipal, los vecinos y la hacienda local.'}, correct:'b', why:{b:'La LBRL establece que el municipio es la entidad local básica y sus elementos son el territorio (término municipal), la población (el municipio agrupa a los vecinos) y la organización (el Ayuntamiento).'}},
{n:14, q:'El término municipal es:', o:{a:'La delimitación geográfica del municipio.',b:'El conjunto de vecinos del municipio.',c:'El órgano de gobierno del municipio.',d:'La sede del Ayuntamiento.'}, correct:'c', why:{c:'El término municipal es el territorio en que el Ayuntamiento ejerce sus competencias, es decir, la delimitación geográfica del municipio.'}},
{n:15, q:'El Padrón municipal es el registro administrativo donde constan los vecinos del municipio. Sus datos constituyen prueba de la residencia en el municipio y del domicilio habitual en el mismo. La gestión del Padrón corresponde a:', o:{a:'El INE.',b:'Los Ayuntamientos.',c:'El Ministerio del Interior.',d:'La Diputación Provincial.'}, correct:'a', why:{a:'Conforme a la LBRL y la Ley de Bases de Régimen Local, la gestión del Padrón municipal corresponde a los Ayuntamientos, aunque el INE coordina y supervisa las operaciones necesarias.'}},
{n:16, q:'La condición de vecino se adquiere:', o:{a:'Por empadronamiento en el municipio.',b:'Por nacer en el municipio.',c:'Por residir más de 5 años en el municipio.',d:'Por decisión del Ayuntamiento.'}, correct:'b', why:{b:'Conforme a la LBRL, la inscripción en el Padrón municipal como residente en el municipio otorga la condición de vecino del mismo.'}},
{n:17, q:'El Alcalde puede ser removido por el Pleno del Ayuntamiento mediante:', o:{a:'Moción de censura.',b:'Votación de dos tercios de los Concejales.',c:'Referéndum de los vecinos.',d:'Decisión del Gobernador Civil.'}, correct:'a', why:{a:'La LBRL establece que el Alcalde puede ser destituido por el Pleno del Ayuntamiento mediante moción de censura aprobada por la mayoría absoluta de los Concejales.'}},
{n:18, q:'La Junta de Gobierno Local:', o:{a:'Existe en todos los municipios.',b:'Asiste al Alcalde en sus funciones y puede asumir competencias delegadas.',c:'Es presidida por el Teniente de Alcalde de mayor edad.',d:'Tiene poder legislativo local.'}, correct:'b', why:{b:'La Junta de Gobierno Local (antes Comisión de Gobierno) asiste al Alcalde en el ejercicio de sus atribuciones y puede ejercer las competencias que el Alcalde u otro órgano deleguen en ella.'}},
{n:19, q:'¿En qué municipios es obligatoria la existencia de Junta de Gobierno Local?', o:{a:'En todos los municipios.',b:'En los de más de 5.000 habitantes.',c:'En los de más de 10.000 habitantes.',d:'En los de más de 20.000 habitantes.'}, correct:'c', why:{c:'La LBRL establece que la Junta de Gobierno Local es obligatoria en municipios con población superior a 5.000 habitantes, aunque puede existir en municipios menores si así lo acuerda el Pleno.'}},
{n:20, q:'Las competencias municipales:', o:{a:'Son solo las expresamente atribuidas por ley.',b:'Incluyen todas las materias que afecten a los intereses de los vecinos.',c:'Son las que les deleguen las CCAA.',d:'Son determinadas por el Gobierno Central.'}, correct:'a', why:{a:'Conforme al principio de legalidad local, los municipios ejercen las competencias que les atribuyen las leyes, tanto las propias como las delegadas.'}},
{n:21, q:'Las competencias propias de los municipios son ejercidas:', o:{a:'Bajo la supervisión del Gobierno.',b:'En régimen de autonomía y bajo su propia responsabilidad.',c:'Con la tutela de la Diputación Provincial.',d:'Previa autorización de la CCAA.'}, correct:'a', why:{a:'Las competencias propias de los municipios se ejercen en régimen de autonomía y bajo la propia responsabilidad del municipio, sin sujeción a instrucciones de otras administraciones.'}},
{n:22, q:'La Diputación Provincial tiene como finalidad:', o:{a:'Controlar la actuación de los municipios.',b:'Garantizar los principios de solidaridad y equilibrio intermunicipales en el marco de la política económica y social.',c:'Sustituir a los municipios en el ejercicio de sus competencias.',d:'Recaudar los impuestos provinciales.'}, correct:'c', why:{c:'La Diputación Provincial tiene como finalidad garantizar los principios de solidaridad y equilibrio intermunicipales, y cooperar con los municipios para el ejercicio eficaz de sus competencias.'}},
{n:23, q:'Las Comunidades Autónomas se constituyeron al amparo de:', o:{a:'El Título VII de la CE.',b:'El Título VIII de la CE.',c:'El Título IX de la CE.',d:'El Título VI de la CE.'}, correct:'c', why:{c:'Las Comunidades Autónomas se regulan en el Título VIII de la Constitución Española, arts. 143 a 158.'}},
{n:24, q:'Las Comunidades Autónomas pueden acceder a su autonomía por dos vías. ¿Cuál es la vía del art.151 CE?', o:{a:'La vía ordinaria o lenta.',b:'La vía especial o rápida, reservada a territorios con especiales características.',c:'La vía aplicable a todas las CCAA por igual.',d:'La vía exclusiva para las CCAA insulares.'}, correct:'d', why:{d:'El art.151 CE establecía la vía rápida o especial de acceso a la autonomía, que permitía asumir desde el inicio el máximo de competencias, aplicada históricamente a Cataluña, País Vasco, Galicia y Andalucía.'}},
{n:25, q:'La iniciativa para el proceso autonómico en la vía del art.143 CE corresponde a:', o:{a:'Las Diputaciones Provinciales o los órganos interinsulares correspondientes y las dos terceras partes de los municipios cuya población represente la mayoría del censo electoral de cada provincia o isla.',b:'Solo el Gobierno Central.',c:'Solo los ciudadanos mediante referéndum.',d:'El Senado.'}, correct:'b', why:{b:'El art.143.2 CE establece que la iniciativa del proceso autonómico corresponde a todas las Diputaciones interesadas o al órgano interinsular correspondiente y a las dos terceras partes de los municipios cuya población represente la mayoría del censo electoral de cada provincia o isla.'}},
{n:26, q:'El Estatuto de Autonomía es:', o:{a:'Un reglamento autonómico.',b:'La norma institucional básica de cada Comunidad Autónoma, reconocida y amparada por el Estado como parte integrante del ordenamiento jurídico.',c:'Una ley ordinaria autonómica.',d:'Un decreto del Gobierno Central.'}, correct:'d', why:{d:'El art.147.1 CE establece que dentro de los términos de la Constitución, los Estatutos serán la norma institucional básica de cada Comunidad Autónoma, reconocida y amparada por el Estado como parte integrante del ordenamiento jurídico.'}},
{n:27, q:'Los Estatutos de Autonomía son aprobados por:', o:{a:'Las Cortes Generales mediante ley orgánica.',b:'El Gobierno Central.',c:'Solo el Parlamento autonómico.',d:'El Senado exclusivamente.'}, correct:'d', why:{d:'Los Estatutos de Autonomía son aprobados por las Cortes Generales mediante ley orgánica, conforme al art.147.3 CE.'}},
{n:28, q:'Las competencias exclusivas del Estado se enumeran en:', o:{a:'El art.148 CE.',b:'El art.149 CE.',c:'El art.150 CE.',d:'El art.151 CE.'}, correct:'d', why:{d:'El art.149 CE enumera las materias sobre las que el Estado tiene competencia exclusiva.'}},
{n:29, q:'Las competencias que pueden asumir las Comunidades Autónomas se enumeran en:', o:{a:'El art.148 CE.',b:'El art.149 CE.',c:'El art.150 CE.',d:'El art.151 CE.'}, correct:'d', why:{d:'El art.148 CE establece las materias sobre las que las Comunidades Autónomas podrán asumir competencias.'}},
{n:30, q:'En el caso de que el Estado no haya establecido la legislación básica en una materia, las Comunidades Autónomas pueden actuar en esa materia hasta que el Estado lo haga. Este principio se denomina:', o:{a:'Principio de prevalencia.',b:'Principio de supletoriedad.',c:'Principio de subsidiariedad.',d:'Principio de competencia.'}, correct:'c', why:{c:'El art.149.3 CE establece que el derecho estatal será, en todo caso, supletorio del derecho de las Comunidades Autónomas. El principio de supletoriedad permite al derecho estatal complementar el autonómico cuando este sea insuficiente.'}},
{n:31, q:'El art.149.3 CE establece que las materias no atribuidas expresamente al Estado por la Constitución:', o:{a:'Corresponden al Estado.',b:'Corresponden a las CCAA si así lo establecen sus Estatutos.',c:'Son de libre disposición de los ciudadanos.',d:'Corresponden a las provincias.'}, correct:'b', why:{b:'El art.149.3 CE establece que las materias no atribuidas expresamente al Estado por la Constitución podrán corresponder a las CCAA en virtud de sus respectivos Estatutos.'}},
{n:32, q:'El art.150 CE prevé la posibilidad de que el Estado transfiera o delegue en las CCAA competencias propias del Estado. Las leyes que vehiculan esta transferencia se denominan:', o:{a:'Leyes de armonización.',b:'Leyes orgánicas de transferencia o delegación.',c:'Leyes marco.',d:'Leyes de bases.'}, correct:'b', why:{b:'El art.150.2 CE establece que el Estado podrá transferir o delegar en las CCAA, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal.'}},
{n:33, q:'El Fondo de Compensación Interterritorial tiene como finalidad:', o:{a:'Financiar los servicios comunes del Estado.',b:'Corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad.',c:'Subvencionar las actividades culturales de las CCAA.',d:'Financiar las infraestructuras del Estado en las CCAA.'}, correct:'a', why:{a:'El art.158.2 CE establece que con el fin de corregir desequilibrios económicos interterritoriales y hacer efectivo el principio de solidaridad, se constituirá un Fondo de Compensación con destino a gastos de inversión.'}},
{n:34, q:'España tiene actualmente:', o:{a:'15 Comunidades Autónomas y 2 Ciudades Autónomas.',b:'17 Comunidades Autónomas y 2 Ciudades Autónomas.',c:'17 Comunidades Autónomas.',d:'19 Comunidades Autónomas.'}, correct:'a', why:{a:'España está organizada en 17 Comunidades Autónomas y 2 Ciudades Autónomas (Ceuta y Melilla).'}},
{n:35, q:'¿Cuáles son las instituciones de autogobierno propias de las Comunidades Autónomas?', o:{a:'Una Asamblea Legislativa, un Consejo de Gobierno y un Tribunal Superior de Justicia.',b:'Solo una Asamblea Legislativa y un Presidente.',c:'Una Asamblea Legislativa, un Consejo de Gobierno, un Presidente y un Tribunal Superior de Justicia.',d:'El Parlamento autonómico y el Presidente.'}, correct:'a', why:{a:'El art.152.1 CE establece que las CCAA constituidas por la vía del art.151 tendrán como instituciones propias: una Asamblea Legislativa elegida por sufragio universal, un Consejo de Gobierno con funciones ejecutivas y administrativas y un Tribunal Superior de Justicia.'}},
{n:36, q:'El Presidente de la Comunidad Autónoma:', o:{a:'Es elegido directamente por los ciudadanos.',b:'Es nombrado por el Rey a propuesta del Parlamento autonómico y dirige el Consejo de Gobierno.',c:'Es designado por el Gobierno Central.',d:'Es el Presidente de la Asamblea Legislativa.'}, correct:'c', why:{c:'El Presidente de la CCAA es elegido por la Asamblea Legislativa y nombrado por el Rey. Dirige el Consejo de Gobierno y ostenta la suprema representación de la CCAA y la ordinaria del Estado en la misma.'}},
{n:37, q:'El control de la constitucionalidad de las leyes autonómicas corresponde a:', o:{a:'El Tribunal Supremo.',b:'El Gobierno Central.',c:'El Tribunal Constitucional.',d:'El Tribunal Superior de Justicia de la CCAA.'}, correct:'c', why:{c:'El control de constitucionalidad de las leyes, tanto estatales como autonómicas, corresponde exclusivamente al Tribunal Constitucional, conforme al art.161 CE.'}},
{n:38, q:'El Senado es definido constitucionalmente como:', o:{a:'La Cámara de representación popular.',b:'La Cámara de representación territorial.',c:'La Cámara de representación autonómica.',d:'La Cámara de representación provincial.'}, correct:'c', why:{c:'El art.69.1 CE define al Senado como la Cámara de representación territorial.'}},
{n:39, q:'La Conferencia de Presidentes Autonómicos es un órgano de:', o:{a:'Coordinación política.',b:'Control de las CCAA.',c:'Cooperación multilateral entre el Gobierno central y los Presidentes de las CCAA.',d:'Elaboración de legislación autonómica.'}, correct:'b', why:{b:'La Conferencia de Presidentes es un órgano de cooperación política de carácter multilateral entre el Gobierno central y los Presidentes de las Comunidades Autónomas.'}},
{n:40, q:'Las Conferencias Sectoriales son órganos de:', o:{a:'Cooperación entre el Estado y las CCAA en materias específicas.',b:'Control estatal sobre las CCAA.',c:'Elaboración de la legislación básica estatal.',d:'Resolución de conflictos entre CCAA.'}, correct:'b', why:{b:'Las Conferencias Sectoriales son órganos de cooperación entre la Administración del Estado y las CCAA en materias específicas sectoriales, como sanidad, educación, etc.'}},
{n:41, q:'El principio de solidaridad entre las CCAA está reconocido en:', o:{a:'El art.2 CE.',b:'El art.138 CE.',c:'El art.149 CE.',d:'El art.156 CE.'}, correct:'b', why:{b:'El art.138.1 CE establece que el Estado garantiza la realización efectiva del principio de solidaridad consagrado en el art.2 CE, velando por el establecimiento de un equilibrio económico adecuado y justo entre las diversas partes del territorio español.'}},
{n:42, q:'La Comunitat Valenciana accedió a la autonomía mediante la vía del:', o:{a:'Art.143 CE.',b:'Art.151 CE.',c:'Art.144 CE.',d:'Disposición Transitoria Segunda de la CE.'}, correct:'c', why:{c:'La Comunitat Valenciana accedió a la autonomía siguiendo la vía del art.143 CE (vía ordinaria), aunque con la particularidad de que su Estatuto fue aprobado por las Cortes mediante ley orgánica, siendo uno de los primeros en aprobarse.'}},
{n:43, q:'El Estatuto de Autonomía de la Comunitat Valenciana está aprobado por:', o:{a:'Ley Orgánica 5/1982, de 1 de julio.',b:'Ley Orgánica 1/2006, de 10 de abril.',c:'Ley Orgánica 3/1979, de 18 de diciembre.',d:'Ley Orgánica 6/2006, de 19 de julio.'}, correct:'c', why:{c:'El vigente Estatuto de Autonomía de la Comunitat Valenciana fue aprobado por la Ley Orgánica 1/2006, de 10 de abril, de Reforma del Estatuto de Autonomía de la Comunitat Valenciana.'}},
{n:44, q:'Las Cortes Valencianas (Les Corts) son el órgano legislativo de la Comunitat Valenciana. ¿Cuántos Diputados las componen?', o:{a:'Un mínimo de 75 y un máximo de 99.',b:'Exactamente 99.',c:'Un mínimo de 60 y un máximo de 99.',d:'Exactamente 75.'}, correct:'a', why:{a:'El Estatuto de Autonomía de la Comunitat Valenciana establece que Les Corts estarán integradas por un número de Diputados no inferior a 75 ni superior a 99.'}},
{n:45, q:'El Presidente de la Generalitat Valenciana:', o:{a:'Es nombrado por el Rey a propuesta del Parlamento autonómico.',b:'Es elegido directamente por los ciudadanos valencianos.',c:'Es designado por el Gobierno Central.',d:'Es el Presidente de Les Corts.'}, correct:'d', why:{d:'El Presidente de la Generalitat es elegido por Les Corts de entre sus miembros y nombrado por el Rey. Ostenta la suprema representación de la Comunitat Valenciana.'}},
{n:46, q:'El Consell es el órgano de gobierno y administración de la Generalitat Valenciana. El President del Consell:', o:{a:'Es elegido directamente por los ciudadanos.',b:'Ostenta la suprema representación de la Comunitat Valenciana y la ordinaria del Estado en la misma.',c:'Es designado por el Gobierno central.',d:'Es el Alcalde de Valencia.'}, correct:'b', why:{b:'El President del Consell dirige la acción del Gobierno valenciano y ostenta la suprema representación de la Comunitat Valenciana y la representación ordinaria del Estado en el territorio.'}},
{n:47, q:'El Tribunal Superior de Justicia de la Comunitat Valenciana:', o:{a:'Es el órgano superior de la jurisdicción en el territorio de la CCAA.',b:'Tiene competencias exclusivas en materia civil.',c:'Depende directamente del Tribunal Constitucional.',d:'Es elegido por Les Corts.'}, correct:'a', why:{a:'El Tribunal Superior de Justicia de la Comunitat Valenciana es el órgano jurisdiccional superior en el ámbito de la CCAA, sin perjuicio de la jurisdicción que corresponde al Tribunal Supremo.'}},
{n:48, q:'El Síndic de Greuges de la Comunitat Valenciana es:', o:{a:'El equivalente autonómico del Defensor del Pueblo.',b:'El Presidente del Tribunal Superior de Justicia valenciano.',c:'El Secretario General de Les Corts.',d:'El Interventor General de la Generalitat.'}, correct:'b', why:{b:'El Síndic de Greuges es el comisionado parlamentario de Les Corts que supervisa la actividad de la Administración autonómica y local valenciana en defensa de los derechos fundamentales de los ciudadanos.'}},
{n:49, q:'La Sindicatura de Comptes de la Comunitat Valenciana es:', o:{a:'El órgano fiscalizador de las cuentas públicas de la Generalitat.',b:'El órgano recaudador de tributos de la Generalitat.',c:'El órgano asesor del Consell en materia económica.',d:'El organismo que gestiona la deuda pública autonómica.'}, correct:'b', why:{b:'La Sindicatura de Comptes es el órgano de control externo de la gestión económica, financiera y contable del sector público valenciano, equivalente al Tribunal de Cuentas en el ámbito autonómico.'}},
{n:50, q:'El Consell Jurídic Consultiu de la Comunitat Valenciana:', o:{a:'Es el órgano asesor del Consell en materia jurídica.',b:'Es el equivalente autonómico del Tribunal Constitucional.',c:'Es el órgano de selección de funcionarios autonómicos.',d:'Controla el presupuesto de la Generalitat.'}, correct:'b', why:{b:'El Consell Jurídic Consultiu es el supremo órgano consultivo del Consell y de la Administración autonómica y local valenciana, equivalente al Consejo de Estado en el ámbito estatal.'}},
{n:51, q:'La Constitución Española reconoce el derecho a la autonomía de las nacionalidades y regiones en el artículo:', o:{a:'Art.2 CE.',b:'Art.137 CE.',c:'Art.143 CE.',d:'Art.148 CE.'}, correct:'c', why:{c:'El art.2 CE reconoce y garantiza el derecho a la autonomía de las nacionalidades y regiones que integran la Nación española, junto con la solidaridad entre todas ellas.'}},
{n:52, q:'La Constitución Española establece que la soberanía nacional reside en:', o:{a:'Las Cortes Generales.',b:'El Rey.',c:'El pueblo español.',d:'El Gobierno.'}, correct:'a', why:{a:'El art.1.2 CE establece que la soberanía nacional reside en el pueblo español, del que emanan los poderes del Estado.'}},
{n:53, q:'El art.143 CE establece la vía ordinaria de acceso a la autonomía. Para iniciar el proceso autonómico se requería la iniciativa de:', o:{a:'Solo las Diputaciones Provinciales.',b:'Las Diputaciones y las dos terceras partes de los municipios con mayoría del censo.',c:'El Gobierno Central.',d:'El Senado.'}, correct:'c', why:{c:'El art.143.2 CE establece que la iniciativa del proceso autonómico corresponde a las Diputaciones interesadas o al órgano interinsular y a las dos terceras partes de los municipios cuya población represente la mayoría del censo electoral.'}},
{n:54, q:'El art.148.2 CE establece que transcurridos cinco años desde la aprobación del Estatuto de Autonomía, las CCAA podrán:', o:{a:'Solicitar su incorporación a otra CCAA.',b:'Ampliar sucesivamente sus competencias mediante reforma del Estatuto.',c:'Exigir competencias exclusivas en cualquier materia.',d:'Disolver su Asamblea Legislativa.'}, correct:'a', why:{a:'El art.148.2 CE establece que transcurridos cinco años, las CCAA podrán, mediante reforma de sus Estatutos, ampliar sucesivamente sus competencias dentro del marco establecido en el art.149.'}},
{n:55, q:'¿Qué es el principio de prevalencia del Derecho estatal?', o:{a:'Las normas estatales son siempre superiores a las autonómicas.',b:'Las normas del Estado prevalecerán sobre las de las CCAA en todo lo que no esté atribuido a la exclusiva competencia de éstas.',c:'Las CCAA deben adaptar sus normas a las del Estado.',d:'El Estado puede anular cualquier norma autonómica.'}, correct:'d', why:{d:'El art.149.3 CE establece el principio de prevalencia del Derecho estatal: las normas del Estado prevalecerán, en caso de conflicto, sobre las de las CCAA en todo lo que no esté atribuido a la exclusiva competencia de éstas.'}},
{n:56, q:'Según la CE, el Estado puede intervenir para obligar a las CCAA al cumplimiento de sus obligaciones constitucionales mediante:', o:{a:'Decreto del Gobierno.',b:'Ley orgánica.',c:'El mecanismo del art.155 CE.',d:'Resolución del Tribunal Constitucional.'}, correct:'c', why:{c:'El art.155 CE establece que si una CCAA no cumpliere las obligaciones que la Constitución u otras leyes le impongan, el Gobierno, previo requerimiento al Presidente de la CCAA y en caso de no ser atendido, podrá adoptar las medidas necesarias para obligar a aquélla al cumplimiento forzoso.'}},
{n:57, q:'La aplicación del art.155 CE requiere:', o:{a:'La aprobación por mayoría absoluta del Senado.',b:'La aprobación por mayoría simple del Congreso.',c:'La aprobación por mayoría de dos tercios de las Cortes Generales.',d:'Solo la decisión del Gobierno.'}, correct:'b', why:{b:'El art.155.1 CE establece que el Gobierno, previo requerimiento al Presidente de la CCAA y en caso de no ser atendido, podrá adoptar las medidas necesarias con la aprobación por mayoría absoluta del Senado.'}},
{n:58, q:'El Estatuto de Autonomía debe contener obligatoriamente:', o:{a:'La denominación de la CCAA, su territorio, la denominación y organización de las instituciones propias y las competencias asumidas.',b:'Solo la denominación y el territorio.',c:'Solo las competencias asumidas.',d:'La denominación, el idioma oficial y las competencias.'}, correct:'c', why:{c:'El art.147.2 CE establece el contenido mínimo de los Estatutos: la denominación de la CCAA, la delimitación de su territorio, la denominación y organización de las instituciones autonómicas y las competencias asumidas.'}},
{n:59, q:'La Comunitat Valenciana tiene como capital:', o:{a:'Alicante.',b:'Castellón de la Plana.',c:'Valencia.',d:'No tiene capital oficial designada.'}, correct:'b', why:{b:'El Estatuto de Autonomía de la Comunitat Valenciana y la legislación autonómica establecen que la ciudad de Valencia es la capital de la Comunitat Valenciana y sede de sus instituciones de autogobierno.'}},
{n:60, q:'El territorio de la Comunitat Valenciana comprende el de los municipios integrados en las provincias de:', o:{a:'Alicante, Castellón y Valencia.',b:'Alicante, Murcia y Valencia.',c:'Castellón y Valencia.',d:'Alicante, Castellón, Valencia y parte de Aragón.'}, correct:'a', why:{a:'El Estatuto de Autonomía de la Comunitat Valenciana establece que su territorio comprende el de los municipios integrados en las provincias de Alicante, Castellón y Valencia.'}},
{n:61, q:'¿Cuál es el idioma cooficial de la Comunitat Valenciana junto al castellano?', o:{a:'El catalán.',b:'El valenciano.',c:'El valenciano o el catalán, según la zona.',d:'No existe idioma cooficial.'}, correct:'d', why:{d:'El art.6 del Estatuto de Autonomía de la Comunitat Valenciana establece que los dos idiomas oficiales de la Comunitat Valenciana son el valenciano y el castellano.'}},
{n:62, q:'Le Corts Valencianes están reguladas en el Estatuto de Autonomía en el Capítulo:', o:{a:'Primero del Título II.',b:'Segundo del Título II.',c:'Primero del Título III.',d:'Primero del Título I.'}, correct:'a', why:{a:'Les Corts están reguladas en el Capítulo Primero del Título II del Estatuto de Autonomía de la Comunitat Valenciana.'}},
{n:63, q:'Los Diputados de Les Corts Valencianes son elegidos por:', o:{a:'Sufragio universal, igual, libre, directo y secreto.',b:'Las Diputaciones Provinciales.',c:'El Consell.',d:'El Gobierno Central.'}, correct:'c', why:{c:'Los Diputados de Les Corts son elegidos por sufragio universal, igual, libre, directo y secreto, en circunscripción provincial, conforme al Estatuto de Autonomía.'}},
{n:64, q:'El President de la Generalitat es elegido por:', o:{a:'Los ciudadanos valencianos mediante sufragio directo.',b:'Les Corts.',c:'El Consell.',d:'El Rey directamente.'}, correct:'d', why:{d:'El President de la Generalitat es elegido por Les Corts Valencianes de entre sus miembros y nombrado por el Rey.'}},
{n:65, q:'El Consell de la Generalitat Valenciana es el órgano colegiado de gobierno de la Generalitat, integrado por:', o:{a:'El President y los Consellers.',b:'Solo los Consellers.',c:'El President, el Vicepresident y los Consellers.',d:'El President, los Secretarios y los Consellers.'}, correct:'b', why:{b:'El Consell de la Generalitat está integrado por el President, el Vicepresident o Vicepresidents en su caso, y los Consellers.'}},
{n:66, q:'El Síndic de Greuges es elegido por:', o:{a:'Les Corts Valencianes.',b:'El Consell.',c:'El President de la Generalitat.',d:'El Gobierno Central.'}, correct:'a', why:{a:'El Síndic de Greuges es elegido por Les Corts Valencianes por una mayoría de tres quintas partes de sus miembros, para un mandato de cinco años.'}},
{n:67, q:'El Síndic de Greuges tiene un mandato de:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Indefinido.'}, correct:'c', why:{c:'El Síndic de Greuges de la Comunitat Valenciana es elegido por Les Corts para un mandato de cinco años, renovable.'}},
{n:68, q:'La Sindicatura de Comptes de la Comunitat Valenciana controla:', o:{a:'Solo los gastos del Consell.',b:'La actividad económico-financiera del sector público valenciano.',c:'Los gastos de los municipios valencianos.',d:'Solo los gastos de Les Corts.'}, correct:'b', why:{b:'La Sindicatura de Comptes ejerce el control externo de la gestión económica, financiera y contable del sector público valenciano, incluyendo la Generalitat, sus organismos autónomos y entes públicos.'}},
{n:69, q:'¿Qué es la Acadèmia Valenciana de la Llengua?', o:{a:'Un organismo para la normalización del valenciano.',b:'Un departamento de la Universitat de València.',c:'Una institución estatutaria cuya función es determinar y elaborar la normativa lingüística del valenciano.',d:'Un organismo del Gobierno Central para la protección del patrimonio lingüístico.'}, correct:'c', why:{c:'La Acadèmia Valenciana de la Llengua es la institución normativa del idioma valenciano cuya función es determinar y elaborar, en su caso, la normativa lingüística del idioma valenciano.'}},
{n:70, q:'¿Cuántas provincias integran la Comunitat Valenciana?', o:{a:'Dos.',b:'Tres.',c:'Cuatro.',d:'Cinco.'}, correct:'a', why:{a:'La Comunitat Valenciana está integrada por tres provincias: Alicante, Castellón y Valencia.'}},
{n:71, q:'Según el Estatuto de Autonomía, la Generalitat Valenciana tiene competencia exclusiva en materia de:', o:{a:'Comercio exterior.',b:'Agricultura y ganadería.',c:'Organización de sus instituciones de autogobierno.',d:'Telecomunicaciones.'}, correct:'c', why:{c:'El Estatuto de Autonomía de la Comunitat Valenciana atribuye a la Generalitat competencia exclusiva en la organización de sus instituciones de autogobierno, entre otras muchas materias.'}},
{n:72, q:'La financiación de las CCAA de régimen común se basa en:', o:{a:'Solo las transferencias del Estado.',b:'Un sistema de financiación basado en tributos cedidos, participación en ingresos del Estado y otros recursos.',c:'La recaudación de todos los impuestos en su territorio.',d:'Solo los tributos propios de la CCAA.'}, correct:'c', why:{c:'La financiación de las CCAA de régimen común se articula mediante tributos cedidos total o parcialmente, participación en los ingresos del Estado, tributos propios y otros recursos, conforme a la LOFCA.'}},
{n:73, q:'El régimen foral navarro y vasco difiere del régimen común en materia de:', o:{a:'Organización institucional.',b:'Financiación, mediante el sistema de Concierto Económico (País Vasco) y Convenio (Navarra).',c:'Competencias legislativas.',d:'Control del Tribunal Constitucional.'}, correct:'a', why:{a:'El rasgo fundamental diferencial del régimen foral del País Vasco y Navarra respecto al común es la financiación: el sistema de Concierto Económico (País Vasco) y Convenio Económico (Navarra).'}},
{n:74, q:'Las Ciudades Autónomas de Ceuta y Melilla:', o:{a:'Tienen el mismo régimen que las CCAA.',b:'Tienen un régimen especial establecido por la CE.',c:'Tienen un estatuto de ciudad autónoma aprobado por ley orgánica.',d:'Dependen directamente del Gobierno Central.'}, correct:'b', why:{b:'Ceuta y Melilla tienen un estatuto especial de ciudad autónoma, aprobado mediante Ley Orgánica, con un régimen de autogobierno diferenciado del de las CCAA.'}},
{n:75, q:'La colaboración entre el Estado y las CCAA se articula principalmente a través de:', o:{a:'Convenios de colaboración y acuerdos de cooperación.',b:'Órdenes ministeriales.',c:'Decretos del Gobierno Central.',d:'Resoluciones del Senado.'}, correct:'d', why:{d:'La colaboración entre el Estado y las CCAA se articula principalmente a través de convenios de colaboración, acuerdos de cooperación y los órganos multilaterales como las Conferencias Sectoriales.'}},
{n:76, q:'El principio de lealtad constitucional en las relaciones interadministrativas exige:', o:{a:'Que las CCAA obedezcan siempre al Estado.',b:'Que el Estado y las CCAA actúen con lealtad y buena fe en sus relaciones mutuas.',c:'Que las CCAA adopten las mismas leyes que el Estado.',d:'Que el Gobierno Central supervise todas las actuaciones autonómicas.'}, correct:'c', why:{c:'El principio de lealtad institucional o constitucional exige que el Estado y las CCAA ajusten el ejercicio de sus respectivas competencias a la consideración del interés general y actúen de buena fe en sus relaciones mutuas.'}},
{n:77, q:'¿En qué órgano está representado el interés autonómico en el ámbito estatal por excelencia?', o:{a:'El Congreso de los Diputados.',b:'El Senado.',c:'El Consejo de Estado.',d:'El Consejo de Política Fiscal y Financiera.'}, correct:'b', why:{b:'El Senado es la Cámara de representación territorial por excelencia (art.69.1 CE) y es el órgano en el que se articula constitucionalmente la participación autonómica en el ámbito estatal.'}},
{n:78, q:'Los conflictos de competencia entre el Estado y las CCAA son resueltos por:', o:{a:'El Senado.',b:'El Gobierno.',c:'El Tribunal Constitucional.',d:'El Tribunal Supremo.'}, correct:'d', why:{d:'Los conflictos de competencia entre el Estado y las CCAA, o entre las propias CCAA, son resueltos por el Tribunal Constitucional conforme al art.161.1.c CE.'}},
{n:79, q:'La Generalitat Valenciana tiene competencia para dictar normas con rango de ley en las materias de su competencia. Estas normas se denominan:', o:{a:'Reales Decretos Legislativos.',b:'Leyes de Les Corts.',c:'Ordenanzas Autonómicas.',d:'Decretos del Consell.'}, correct:'a', why:{a:'Las normas con rango de ley aprobadas por Les Corts Valencianes se denominan Leyes, y tienen el mismo rango que las leyes estatales en el ámbito de las competencias autonómicas.'}},
{n:80, q:'¿Cuál es la norma que regula el proceso de distribución de competencias entre el Estado y las CCAA en materia de financiación?', o:{a:'La LOFCA (Ley Orgánica de Financiación de las CCAA).',b:'La LBRL.',c:'Los Estatutos de Autonomía exclusivamente.',d:'El Presupuesto General del Estado.'}, correct:'a', why:{a:'La LOFCA (Ley Orgánica 8/1980, de 22 de septiembre, de Financiación de las Comunidades Autónomas) es la norma que establece el sistema de financiación autonómica de régimen común.'}},
{n:81, q:'La competencia del Estado para dictar legislación básica y la competencia de las CCAA para el desarrollo legislativo y la ejecución se denomina:', o:{a:'Competencia exclusiva.',b:'Competencia compartida o concurrente.',c:'Competencia delegada.',d:'Competencia residual.'}, correct:'d', why:{d:'La competencia compartida o concurrente es aquella en la que el Estado dicta la legislación básica y las CCAA la desarrollan y ejecutan. Es la forma más común de distribución de competencias en el sistema español.'}},
{n:82, q:'¿Qué órgano de la Generalitat Valenciana es el equivalente al Consejo de Ministros estatal?', o:{a:'Les Corts.',b:'El Consell.',c:'La Sindicatura de Comptes.',d:'El Tribunal Superior de Justicia.'}, correct:'b', why:{b:'El Consell de la Generalitat Valenciana es el órgano colegiado de gobierno y administración de la CCAA, equivalente al Consejo de Ministros en el ámbito estatal.'}},
{n:83, q:'El control de la actividad de la Generalitat Valenciana por las Cortes Generales se ejerce mediante:', o:{a:'El Tribunal Constitucional.',b:'El Senado directamente.',c:'Los mecanismos previstos en la CE y en el Estatuto de Autonomía.',d:'El Defensor del Pueblo.'}, correct:'d', why:{d:'El control de la actividad de las CCAA por las Cortes Generales se ejerce a través de los mecanismos constitucionales como el art.155 CE, y de los instrumentos de coordinación y cooperación interadministrativa.'}},
{n:84, q:'Las tres circunscripciones electorales de Les Corts Valencianes son:', o:{a:'Norte, Centro y Sur.',b:'Alicante, Castellón y Valencia.',c:'Alta, Media y Baja Comunitat.',d:'Litoral, Interior y Mediterránea.'}, correct:'c', why:{c:'Les Corts Valencianes se eligen por circunscripción provincial: Alicante, Castellón y Valencia, conforme al Estatuto de Autonomía y la Ley Electoral Valenciana.'}},
{n:85, q:'La Junta Electoral Central:', o:{a:'Es un órgano de la Generalitat Valenciana.',b:'Es el órgano superior de la Administración Electoral del Estado.',c:'Depende del Ministerio del Interior.',d:'Es presidida por el Ministro de Justicia.'}, correct:'d', why:{d:'La Junta Electoral Central es el órgano superior de la Administración Electoral, con carácter permanente, que está integrada por ocho vocales magistrados del Tribunal Supremo y cinco vocales catedráticos de Derecho.'}},
{n:86, q:'El régimen jurídico de las Haciendas Locales en España se regula principalmente en:', o:{a:'La LBRL.',b:'El Real Decreto Legislativo 2/2004 (Texto Refundido de la Ley Reguladora de las Haciendas Locales).',c:'La LOFCA.',d:'Los Estatutos de Autonomía.'}, correct:'a', why:{a:'El Real Decreto Legislativo 2/2004, de 5 de marzo, por el que se aprueba el Texto Refundido de la Ley Reguladora de las Haciendas Locales, es la norma básica de la financiación de las Entidades Locales.'}},
{n:87, q:'¿Qué es la potestad tributaria municipal?', o:{a:'La facultad del Ayuntamiento de crear impuestos estatales.',b:'La facultad del Ayuntamiento de establecer, gestionar y recaudar sus propios tributos conforme a la ley.',c:'La facultad de exigir tasas estatales.',d:'La facultad de recaudar impuestos autonómicos.'}, correct:'d', why:{d:'La potestad tributaria municipal es la facultad reconocida por la ley a los municipios para establecer, gestionar y recaudar sus propios tributos (impuestos, tasas y contribuciones especiales) dentro del marco legal establecido.'}},
{n:88, q:'El Impuesto sobre Bienes Inmuebles (IBI) es:', o:{a:'Un impuesto estatal gestionado por los municipios.',b:'Un impuesto municipal de exacción obligatoria.',c:'Un impuesto autonómico.',d:'Un impuesto voluntario para los municipios.'}, correct:'a', why:{a:'El IBI es un impuesto local de exacción obligatoria, regulado en el Texto Refundido de la Ley Reguladora de las Haciendas Locales, que grava el valor de los bienes inmuebles urbanos y rústicos.'}},
{n:89, q:'El Impuesto sobre Actividades Económicas (IAE) es:', o:{a:'Un impuesto estatal.',b:'Un impuesto municipal de exacción obligatoria.',c:'Un impuesto autonómico.',d:'Un impuesto municipal voluntario.'}, correct:'a', why:{a:'El IAE es un tributo directo de carácter real, cuyo hecho imponible está constituido por el mero ejercicio de actividades empresariales, profesionales o artísticas. Es de exacción obligatoria municipal.'}},
{n:90, q:'La Mancomunidad de Municipios es:', o:{a:'Una provincia de nueva creación.',b:'Una asociación voluntaria de municipios para la gestión en común de obras o servicios.',c:'Una Entidad Local de creación obligatoria.',d:'Un organismo de la Diputación Provincial.'}, correct:'d', why:{d:'La Mancomunidad es una entidad local creada mediante la asociación voluntaria de dos o más municipios para la gestión en común de obras y servicios de su competencia.'}},
{n:91, q:'Los Consorcios son:', o:{a:'Asociaciones de municipios y otras Administraciones Públicas para fines de interés común.',b:'Organismos autónomos de la Diputación.',c:'Entes supramunicipales de creación obligatoria.',d:'Órganos de control de la Administración Local.'}, correct:'a', why:{a:'Los Consorcios son entidades públicas de carácter asociativo, creadas por Administraciones Públicas y, en su caso, entidades privadas sin ánimo de lucro, para fines de interés público común.'}},
{n:92, q:'¿Cuál de las siguientes es una Entidad Local de ámbito superior al municipio?', o:{a:'La Junta Vecinal.',b:'El Consejo Abierto.',c:'La Comarca.',d:'La Entidad Local Menor.'}, correct:'a', why:{a:'La Comarca es una Entidad Local de ámbito supramunicipal, formada por la agrupación de municipios limítrofes con características geográficas, económicas e históricas comunes.'}},
{n:93, q:'El Consejo Abierto es:', o:{a:'Un órgano de participación ciudadana de los grandes municipios.',b:'El régimen municipal propio de municipios de pequeña población.',c:'Un órgano consultivo de la Diputación.',d:'El órgano de gobierno de las Entidades Locales Menores.'}, correct:'b', why:{b:'El Consejo Abierto es un sistema de gobierno municipal aplicable a municipios de muy reducida población (menos de 100 habitantes) donde todos los vecinos mayores de edad con derecho de sufragio activo participan directamente en la gestión del municipio.'}},
{n:94, q:'El Pleno del Ayuntamiento es el órgano:', o:{a:'Ejecutivo del Ayuntamiento.',b:'De control y de impulso de la gestión municipal.',c:'Máximo de gobierno del Ayuntamiento con funciones de control y normativas.',d:'Consultivo del Ayuntamiento.'}, correct:'d', why:{d:'El Pleno del Ayuntamiento, integrado por todos los Concejales y presidido por el Alcalde, es el órgano máximo de representación y decisión del municipio, con funciones normativas, financieras y de control.'}},
{n:95, q:'El mandato de los Concejales es de:', o:{a:'Cuatro años.',b:'Cinco años.',c:'Seis años.',d:'Indefinido hasta la siguiente convocatoria electoral.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:96, q:'Según la LBRL, ¿en qué municipios es obligatoria la existencia de Comisiones Informativas?', o:{a:'En todos los municipios.',b:'En los de más de 5.000 habitantes.',c:'En los de más de 20.000 habitantes.',d:'Solo en los municipios que tienen Junta de Gobierno Local.'}, correct:'c', why:{c:'La LBRL establece que las Comisiones Informativas, integradas exclusivamente por miembros de la Corporación, son obligatorias en los municipios de más de 5.000 habitantes.'}},
{n:97, q:'El Delegado del Gobierno en la Comunitat Valenciana:', o:{a:'Es el máximo representante del Gobierno central en la CCAA.',b:'Pertenece orgánicamente al Gobierno de la Generalitat.',c:'Es nombrado por el Presidente de la Generalitat.',d:'Depende del Ministerio de Hacienda.'}, correct:'b', why:{b:'El Delegado del Gobierno en la Comunitat Valenciana representa al Gobierno central en el territorio autonómico, dirige la Administración periférica del Estado en la CCAA y coordina los servicios estatales en su territorio.'}},
{n:98, q:'Las relaciones entre el municipio y la CCAA se rigen por el principio de:', o:{a:'Jerarquía, estando los municipios subordinados a la CCAA.',b:'Autonomía municipal y cooperación.',c:'Control previo de los actos municipales por la CCAA.',d:'Tutela de la CCAA sobre los municipios.'}, correct:'d', why:{d:'Las relaciones entre los municipios y la CCAA se rigen por los principios de autonomía local, cooperación y coordinación, sin que exista jerarquía ni tutela de la CCAA sobre los municipios.'}},
{n:99, q:'El Alcalde puede delegar sus funciones en:', o:{a:'Solo el Teniente de Alcalde.',b:'Los Tenientes de Alcalde y los Concejales.',c:'Cualquier funcionario municipal.',d:'Solo en los Concejales delegados.'}, correct:'a', why:{a:'El Alcalde puede delegar el ejercicio de sus atribuciones en los Tenientes de Alcalde y en los miembros de la Junta de Gobierno Local, conforme a la LBRL.'}},
{n:100, q:'La moción de censura en el ámbito municipal:', o:{a:'Debe incluir un candidato alternativo a la Alcaldía.',b:'Puede ser presentada por cualquier Concejal.',c:'No existe en el régimen local.',d:'Requiere el respaldo del 50% de los Concejales.'}, correct:'a', why:{a:'La LBRL establece que la moción de censura al Alcalde debe ser suscrita al menos por la mayoría absoluta de los Concejales y debe incluir el candidato a la Alcaldía, siendo constructiva.'}},
{n:101, q:'¿Qué entidad es responsable de la gestión de los servicios de transporte urbano colectivo en los municipios?', o:{a:'La Diputación Provincial.',b:'El propio Ayuntamiento.',c:'La Comunidad Autónoma.',d:'El Estado.'}, correct:'b', why:{b:'Conforme a la LBRL, el transporte colectivo urbano de viajeros es un servicio de prestación obligatoria en los municipios de más de 50.000 habitantes, competencia del propio Ayuntamiento.'}},
{n:102, q:'El servicio de recogida de residuos en los municipios es:', o:{a:'Competencia del Estado.',b:'Competencia de la CCAA.',c:'Prestación obligatoria del municipio.',d:'Competencia de la Diputación Provincial.'}, correct:'c', why:{c:'Conforme a la LBRL, la recogida de residuos es una prestación obligatoria del municipio, independientemente de su población.'}},
{n:103, q:'¿Qué servicio es obligatorio en todos los municipios sin importar su población?', o:{a:'Servicio de extinción de incendios.',b:'Alumbrado público, cementerio, recogida de residuos, limpieza viaria y agua potable.',c:'Biblioteca pública.',d:'Parque público.'}, correct:'d', why:{d:'La LBRL establece que todos los municipios, con independencia de su población, deben prestar: alumbrado público, cementerio, recogida de residuos, limpieza viaria, abastecimiento domiciliario de agua potable, alcantarillado, acceso a núcleos de población y pavimentación.'}},
{n:104, q:'El Defensor del Pueblo tiene competencia para supervisar la actividad de las Administraciones Locales. Sin embargo, la mayoría de las CCAA tienen una figura equivalente autonómica. En la Comunitat Valenciana es:', o:{a:'El Síndic de Greuges.',b:'El Comisionado Parlamentario.',c:'El Ararteko.',d:'El Valedor do Pobo.'}, correct:'a', why:{a:'El Síndic de Greuges es el comisionado parlamentario de Les Corts que ejerce funciones análogas al Defensor del Pueblo en el ámbito de la Comunitat Valenciana.'}},
{n:105, q:'Las Ordenanzas Municipales son:', o:{a:'Normas con rango de ley aprobadas por el Ayuntamiento.',b:'Normas reglamentarias de carácter general aprobadas por el Pleno del Ayuntamiento.',c:'Instrucciones internas del Alcalde.',d:'Normas aprobadas por la Diputación Provincial.'}, correct:'c', why:{c:'Las Ordenanzas Municipales son normas de carácter general, con eficacia normativa externa, aprobadas por el Pleno del Ayuntamiento, que regulan las materias de competencia municipal.'}},
{n:106, q:'Los Reglamentos Orgánicos Municipales:', o:{a:'Regulan la organización y funcionamiento del Ayuntamiento.',b:'Regulan las relaciones del Ayuntamiento con los ciudadanos.',c:'Son normas de rango superior a las Ordenanzas.',d:'Son aprobados por la Diputación Provincial.'}, correct:'d', why:{d:'Los Reglamentos Orgánicos Municipales son normas que regulan la organización interna del Ayuntamiento y el funcionamiento de sus órganos de gobierno y administración.'}},
{n:107, q:'La Carta Municipal es:', o:{a:'Un instrumento de planificación urbanística.',b:'Una norma especial de organización aplicable a municipios de gran población.',c:'El Estatuto del municipio, aprobado por ley autonómica.',d:'Un acuerdo entre el municipio y la CCAA.'}, correct:'b', why:{b:'La Carta Municipal es el conjunto de normas específicas que rigen la organización y el funcionamiento de los municipios de gran población (más de 250.000 habitantes o capitales de provincia de más de 175.000 habitantes).'}},
{n:108, q:'Las Áreas Metropolitanas son:', o:{a:'Entidades Locales creadas obligatoriamente en grandes ciudades.',b:'Entidades Locales de creación potestativa por las CCAA para la prestación de servicios supramunicipales en zonas urbanizadas.',c:'Un tipo especial de mancomunidad.',d:'Zonas de gestión estatal en grandes aglomeraciones urbanas.'}, correct:'a', why:{a:'Las Áreas Metropolitanas son Entidades Locales integradas por los municipios de grandes aglomeraciones urbanas entre cuyos núcleos existan vinculaciones económicas y sociales que hagan necesaria la planificación conjunta y la coordinación de ciertos servicios y obras.'}},
{n:109, q:'El presupuesto municipal es aprobado por:', o:{a:'El Alcalde.',b:'La Junta de Gobierno Local.',c:'El Pleno del Ayuntamiento.',d:'La Diputación Provincial.'}, correct:'d', why:{d:'El presupuesto municipal es competencia del Pleno del Ayuntamiento, que lo aprueba, con carácter anual, antes del 31 de diciembre del ejercicio anterior.'}},
{n:110, q:'¿Qué principio rige la contratación del sector público local?', o:{a:'Libre elección del contratista.',b:'Contratación directa en todos los casos.',c:'Publicidad, concurrencia, igualdad y no discriminación.',d:'Prioridad a las empresas locales.'}, correct:'b', why:{b:'La contratación del sector público local se rige por los principios de publicidad, concurrencia, transparencia, igualdad y no discriminación, conforme a la Ley de Contratos del Sector Público.'}},
{n:111, q:'La responsabilidad patrimonial de las Entidades Locales:', o:{a:'No existe por ser Administraciones Públicas.',b:'Solo se produce por daños físicos a los ciudadanos.',c:'Es objetiva y directa por el funcionamiento normal o anormal de los servicios públicos.',d:'Requiere siempre culpa grave del funcionario.'}, correct:'b', why:{b:'Las Entidades Locales responden patrimonialmente de los daños causados en el ejercicio de sus competencias, conforme al régimen de responsabilidad patrimonial de las Administraciones Públicas (art.106.2 CE).'}},
{n:112, q:'Las elecciones municipales en España se celebran:', o:{a:'Cada cuatro años, coincidiendo con las elecciones autonómicas.',b:'Cada cuatro años, el mismo día que las elecciones al Parlamento Europeo.',c:'Cada cinco años.',d:'Cada cuatro años en fecha variable.'}, correct:'b', why:{b:'Las elecciones municipales se celebran cada cuatro años, y desde 1987 coinciden con las elecciones al Parlamento Europeo.'}},
{n:113, q:'El Interventor Municipal es:', o:{a:'El funcionario responsable del control interno de la gestión económico-financiera del Ayuntamiento.',b:'El representante del Gobierno Central en el municipio.',c:'Un cargo político designado por el Alcalde.',d:'El encargado del control de legalidad de los actos municipales.'}, correct:'a', why:{a:'El Interventor es el funcionario de Administración Local con habilitación de carácter nacional que ejerce el control interno de la gestión económico-financiera y presupuestaria del Ayuntamiento.'}},
{n:114, q:'El Secretario del Ayuntamiento:', o:{a:'Es un cargo de libre designación del Alcalde.',b:'Es un funcionario de Administración Local con habilitación de carácter nacional.',c:'Puede ser cualquier funcionario municipal.',d:'Es nombrado por la Diputación Provincial.'}, correct:'a', why:{a:'El Secretario del Ayuntamiento es un funcionario de Administración Local con habilitación de carácter nacional, al que corresponde la fe pública y el asesoramiento legal preceptivo.'}},
{n:115, q:'En materia de personal, las Entidades Locales pueden tener:', o:{a:'Solo funcionarios de carrera.',b:'Funcionarios de carrera, funcionarios interinos, personal laboral y personal eventual.',c:'Solo personal laboral.',d:'Solo funcionarios de carrera y personal eventual.'}, correct:'d', why:{d:'Las Entidades Locales pueden tener en sus plantillas: funcionarios de carrera, funcionarios interinos, personal laboral (fijo, por tiempo indefinido y temporal) y personal eventual.'}},
{n:116, q:'El régimen de impugnación de los actos municipales ante la jurisdicción contencioso-administrativa requiere previamente:', o:{a:'Recurso de alzada ante la Diputación.',b:'Recurso de reposición potestativo ante el propio Ayuntamiento.',c:'Reclamación previa ante el Estado.',d:'Denuncia ante el Ministerio de Administraciones Públicas.'}, correct:'b', why:{b:'Contra los actos y resoluciones de los órganos municipales puede interponerse recurso de reposición potestativo ante el propio órgano que los dictó, y posteriormente recurso contencioso-administrativo.'}},
{n:117, q:'El Plan General de Ordenación Urbana (PGOU):', o:{a:'Es aprobado por el Ministerio de Fomento.',b:'Es el instrumento de planeamiento urbanístico que regula el suelo del municipio.',c:'Es aprobado por la Diputación Provincial.',d:'Debe ser autorizado por el Gobierno central.'}, correct:'b', why:{b:'El Plan General de Ordenación Urbana (o su equivalente en cada CCAA) es el instrumento básico de planeamiento urbanístico municipal, aprobado inicialmente por el Ayuntamiento y definitivamente por la CCAA.'}},
{n:118, q:'La coordinación de la actividad de los municipios en materia de tráfico corresponde en primer lugar a:', o:{a:'La Policía Nacional.',b:'La Guardia Civil.',c:'Los propios Ayuntamientos, a través de sus Policías Locales.',d:'La Dirección General de Tráfico.'}, correct:'b', why:{b:'La ordenación del tráfico de vehículos y personas en las vías urbanas es competencia municipal, ejercida mediante la Policía Local y el servicio de regulación del tráfico del Ayuntamiento.'}},
{n:119, q:'El Fondo de Compensación Interterritorial se distribuye entre:', o:{a:'Solo las CCAA menos desarrolladas.',b:'Todas las CCAA por igual.',c:'Las CCAA y las Entidades Locales en proporción a su población.',d:'Las CCAA y Ceuta y Melilla.'}, correct:'a', why:{a:'El Fondo de Compensación Interterritorial se destina a las CCAA y provincias de menor nivel de desarrollo relativo, con el objeto de corregir desequilibrios económicos interterritoriales.'}},
{n:120, q:'Las Comunidades Autónomas tienen potestad para dictar normas con rango de ley en su ámbito de competencias. ¿Pueden también dictar decretos legislativos?', o:{a:'No, solo el Estado puede dictar decretos legislativos.',b:'Sí, el Gobierno autonómico puede dictar normas con rango de ley por delegación del Parlamento autonómico.',c:'Solo en casos de urgencia.',d:'Solo con autorización del Estado.'}, correct:'d', why:{d:'Las CCAA pueden dictar Decretos Legislativos cuando sus Parlamentos deleguen en el Gobierno autonómico la elaboración de textos articulados o textos refundidos, de forma análoga al Estado.'}},
{n:121, q:'En el sistema de distribución competencial español, las competencias exclusivas de las CCAA:', o:{a:'Pueden ser asumidas por el Estado en cualquier momento.',b:'No pueden ser interferidas por el Estado.',c:'Pueden ser limitadas por ley orgánica estatal.',d:'Siempre requieren autorización estatal para su ejercicio.'}, correct:'c', why:{c:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:122, q:'El Estatuto de Autonomía puede ser reformado por iniciativa de:', o:{a:'El Gobierno central exclusivamente.',b:'El Parlamento autonómico, la Cortes Generales o el Gobierno.',c:'El Parlamento autonómico o las Cortes Generales, conforme a los procedimientos previstos en el propio Estatuto.',d:'Solo el Senado.'}, correct:'a', why:{a:'La reforma del Estatuto de Autonomía se rige por el procedimiento previsto en el propio Estatuto, que generalmente requiere iniciativa del Parlamento autonómico y aprobación por las Cortes Generales mediante ley orgánica.'}},
{n:123, q:'¿Qué son las comarcas en el ámbito de la Comunitat Valenciana?', o:{a:'Divisiones administrativas obligatorias de la CCAA.',b:'Agrupaciones de municipios creadas por la Generalitat para la gestión de servicios supramunicipales.',c:'Equivalentes a las provincias en otras CCAA.',d:'Órganos desconcentrados de la Diputación Provincial.'}, correct:'c', why:{c:'Las comarcas en la Comunitat Valenciana son entidades locales formadas por la agrupación de municipios limítrofes, vinculadas por características geográficas, históricas o funcionales comunes, creadas mediante ley de Les Corts.'}},
{n:124, q:'La protección de la legalidad urbanística corresponde en primera instancia a:', o:{a:'El Ministerio de Fomento.',b:'La Comunidad Autónoma.',c:'El Ayuntamiento.',d:'Los Tribunales Ordinarios.'}, correct:'b', why:{b:'La protección de la legalidad urbanística es competencia municipal en primera instancia, siendo el Ayuntamiento el que otorga las licencias y adopta las medidas de disciplina urbanística.'}},
{n:125, q:'Los actos del Pleno del Ayuntamiento en los que el Alcalde vote en contra:', o:{a:'Son nulos de pleno derecho.',b:'Son igualmente válidos si se aprueban por mayoría.',c:'Pueden ser vetados por el Alcalde.',d:'Deben ser remitidos a la Diputación Provincial para su aprobación.'}, correct:'d', why:{d:'Los acuerdos del Pleno se adoptan por votación mayoritaria y son válidos aunque el Alcalde vote en contra; el Alcalde no tiene derecho de veto sobre los acuerdos plenarios.'}},
{n:126, q:'El municipio de Madrid tiene un régimen especial reconocido por:', o:{a:'La Constitución Española.',b:'La Ley 22/2006, de Capitalidad y de Régimen Especial de Madrid.',c:'La Ley 57/2003, de Medidas para la Modernización del Gobierno Local.',d:'Un Estatuto específico aprobado por el Senado.'}, correct:'c', why:{c:'El municipio de Madrid tiene su régimen especial de capitalidad regulado en la Ley 22/2006, de 4 de julio, de Capitalidad y de Régimen Especial de Madrid.'}},
{n:127, q:'El principio de subsidiariedad aplicado a las Entidades Locales implica:', o:{a:'Que el Estado siempre actúa antes que los municipios.',b:'Que las decisiones deben adoptarse en el nivel más cercano al ciudadano.',c:'Que los municipios dependen de las CCAA.',d:'Que las CCAA tienen preferencia sobre los municipios.'}, correct:'d', why:{d:'El principio de subsidiariedad implica que las decisiones deben adoptarse en el nivel más próximo al ciudadano que pueda gestionarlas eficazmente, dando preferencia al nivel local sobre el autonómico y estatal.'}},
{n:128, q:'Las Entidades Locales Menores (pedanías, juntas vecinales, etc.):', o:{a:'Son Entidades Locales con plena personalidad jurídica.',b:'Son órganos desconcentrados del municipio.',c:'Son creadas directamente por la CE.',d:'Dependen de la Diputación Provincial.'}, correct:'a', why:{a:'Las Entidades Locales Menores (también llamadas Entidades Locales de ámbito territorial inferior al municipio) tienen reconocida personalidad jurídica propia y son entidades de administración territorial.'}},
{n:129, q:'La Agenda Urbana Española es:', o:{a:'Un plan de ordenación del tráfico en ciudades.',b:'Un instrumento de política pública para el desarrollo urbano sostenible e integrado.',c:'El registro de todos los municipios españoles.',d:'Un plan de financiación de obras municipales.'}, correct:'d', why:{d:'La Agenda Urbana Española es el instrumento de política pública que define los retos y los objetivos que deben guiar la política de cohesión urbana en España, en línea con la Agenda 2030.'}},
{n:130, q:'La Ley de Racionalización y Sostenibilidad de la Administración Local (LRSAL) de 2013 modificó:', o:{a:'La Constitución Española.',b:'La Ley de Bases de Régimen Local y otras normas relacionadas.',c:'Solo la LOFCA.',d:'El Estatuto de Autonomía de las CCAA.'}, correct:'d', why:{d:'La Ley 27/2013, de 27 de diciembre, de Racionalización y Sostenibilidad de la Administración Local (LRSAL) modificó la Ley 7/1985, de 2 de abril, reguladora de las Bases del Régimen Local y otras normas.'}},
{n:131, q:'Según la CE, el Estado podrá impugnar ante el TC las disposiciones y resoluciones adoptadas por las CCAA. La impugnación suspenderá automáticamente la disposición o resolución recurrida cuando:', o:{a:'Lo decida el TC.',b:'Se invoque el art.161.2 CE.',c:'Lo solicite el Gobierno.',d:'Lo decida el Senado.'}, correct:'b', why:{b:'El art.161.2 CE establece que el Gobierno podrá impugnar ante el TC las disposiciones y resoluciones adoptadas por los órganos de las CCAA, produciendo la impugnación la suspensión de la disposición o resolución recurrida cuando se invoque este artículo.'}},
{n:132, q:'El acceso a la función pública local se rige por los principios de:', o:{a:'Mérito, capacidad y publicidad.',b:'Mérito, capacidad, igualdad y publicidad.',c:'Solo mérito y capacidad.',d:'Discrecionalidad del Alcalde.'}, correct:'d', why:{d:'El acceso a la función pública local se rige por los principios de igualdad, mérito, capacidad y publicidad, conforme al art.103.3 CE y la LBRL.'}},
{n:133, q:'¿Qué se entiende por descentralización territorial?', o:{a:'La transferencia de competencias del Estado a las CCAA.',b:'La transferencia de competencias de las Administraciones superiores a las inferiores con personalidad jurídica propia.',c:'La delegación de funciones a funcionarios inferiores.',d:'La eliminación de niveles administrativos.'}, correct:'c', why:{c:'La descentralización territorial es la transferencia de competencias y potestades desde las Administraciones superiores a Administraciones territoriales inferiores con personalidad jurídica propia (CCAA, municipios, etc.).'}},
{n:134, q:'El art.155 CE ha sido aplicado por primera vez en la historia constitucional española en:', o:{a:'1981, durante el intento de golpe de Estado.',b:'2017, en relación con la crisis de Cataluña.',c:'2020, durante la pandemia de COVID-19.',d:'Nunca ha sido aplicado.'}, correct:'b', why:{b:'El art.155 CE fue aplicado por primera vez en octubre de 2017 cuando el Gobierno de España lo activó en relación con la crisis institucional de Cataluña tras la declaración unilateral de independencia.'}},
{n:135, q:'¿Cuál es el plazo máximo para que el Gobierno Central atienda el requerimiento de una CCAA antes de aplicar el art.155 CE?', o:{a:'24 horas.',b:'48 horas.',c:'No hay plazo fijo; el Gobierno lo determina.',d:'15 días.'}, correct:'d', why:{d:'El art.155 CE no establece un plazo concreto para que la CCAA atienda el requerimiento del Gobierno; simplemente señala que si el requerimiento no es atendido, el Gobierno podrá adoptar las medidas necesarias.'}},
{n:136, q:'¿Cuál es el órgano máximo de la Comunitat Valenciana?', o:{a:'El President de la Generalitat.',b:'Les Corts Valencianes.',c:'El Consell.',d:'El Tribunal Superior de Justicia.'}, correct:'a', why:{a:'Les Corts Valencianes es el órgano legislativo y de representación del pueblo valenciano. Junto con el Consell y el President constituyen las tres instituciones de autogobierno de la Generalitat.'}},
{n:137, q:'La Ley 8/2010, de 23 de junio, de la Generalitat, establece el régimen aplicable a la utilización por los municipios valencianos de medios propios personales y materiales de la Generalitat. Este mecanismo se denomina:', o:{a:'Delegación de competencias.',b:'Encomienda de gestión.',c:'Transferencia de funciones.',d:'Convenio de colaboración.'}, correct:'d', why:{d:'La encomienda de gestión es el mecanismo por el que una Administración pública confía la realización de determinadas actividades de carácter material, técnico o de servicios a otra Administración u organismo.'}},
{n:138, q:'¿Qué instrumento permite al Estado delegar competencias propias a una CCAA por un período determinado?', o:{a:'La ley de armonización.',b:'La ley orgánica de transferencia o delegación del art.150.2 CE.',c:'Un convenio de colaboración.',d:'Un Decreto-ley del Gobierno.'}, correct:'a', why:{a:'El art.150.2 CE establece que el Estado podrá transferir o delegar en las CCAA, mediante ley orgánica, facultades correspondientes a materia de titularidad estatal que por su propia naturaleza sean susceptibles de transferencia o delegación.'}},
{n:139, q:'La Diputación Provincial de Valencia tiene su sede en:', o:{a:'Alicante.',b:'Castellón.',c:'Valencia.',d:'Cualquier municipio de la provincia.'}, correct:'b', why:{b:'La Diputación Provincial de Valencia tiene su sede en la ciudad de Valencia, capital de la provincia.'}},
{n:140, q:'¿Cuántos municipios tiene aproximadamente la Comunitat Valenciana?', o:{a:'Más de 500.',b:'Alrededor de 350.',c:'Alrededor de 200.',d:'Más de 1.000.'}, correct:'a', why:{a:'La Comunitat Valenciana tiene más de 540 municipios distribuidos entre las tres provincias: Alicante, Castellón y Valencia.'}},
{n:141, q:'La Conferencia Sectorial de Administración Pública es el órgano de:', o:{a:'Cooperación entre el Estado y las CCAA en materia de función pública y régimen administrativo.',b:'Control estatal sobre las CCAA en materia de personal.',c:'Elaboración de la legislación básica de función pública.',d:'Resolución de conflictos laborales en la Administración Pública.'}, correct:'d', why:{d:'La Conferencia Sectorial de Administración Pública es el órgano de cooperación y coordinación multilateral entre la Administración del Estado y las CCAA en materia de función pública, organización administrativa y modernización.'}},
{n:142, q:'El Consell Económic i Social (CES) de la Comunitat Valenciana es:', o:{a:'Un órgano de gobierno autonómico.',b:'Un órgano consultivo en materia socioeconómica y laboral.',c:'El órgano de control presupuestario de la Generalitat.',d:'El equivalente autonómico del Consejo de Estado.'}, correct:'b', why:{b:'El Consell Econòmic i Social de la Comunitat Valenciana es un órgano consultivo del Consell en materia socioeconómica y laboral, integrado por representantes de los agentes económicos y sociales.'}},
{n:143, q:'Los Planes de Ordenación de Recursos Naturales (PORN) son aprobados por:', o:{a:'El Gobierno Central.',b:'El Ministerio de Medio Ambiente.',c:'La Comunidad Autónoma competente.',d:'Los Ayuntamientos afectados.'}, correct:'a', why:{a:'Los PORN son instrumentos de planificación ambiental aprobados por las Comunidades Autónomas para la ordenación y uso sostenible de los recursos naturales en su territorio.'}},
{n:144, q:'¿Cuál es la diferencia entre la desconcentración y la descentralización administrativa?', o:{a:'La descentralización supone transferencia a órganos con personalidad jurídica propia; la desconcentración, a órganos subordinados dentro de la misma Administración.',b:'Son conceptos sinónimos.',c:'La desconcentración implica creación de nuevas administraciones.',d:'La descentralización es solo territorial; la desconcentración puede ser funcional.'}, correct:'c', why:{c:'La desconcentración es la transferencia de competencias de un órgano superior a otro inferior dentro de la misma Administración, manteniendo la unidad jerárquica. La descentralización supone la transferencia a entes con personalidad jurídica propia e independencia.'}},
{n:145, q:'El Gobierno de España puede ejercer el control de la actividad de las CCAA mediante:', o:{a:'Control de legalidad por los Tribunales, control financiero del Tribunal de Cuentas y delegados del Gobierno.',b:'Órdenes directas al Gobierno autonómico.',c:'Veto de las leyes autonómicas.',d:'Supervisión directa del Ministerio de Administraciones Públicas.'}, correct:'c', why:{c:'El art.153 CE establece los mecanismos de control de la actividad de las CCAA: el TC en materia constitucional, el Gobierno previo dictamen del Consejo de Estado en funciones ejecutivas de la legislación estatal, la jurisdicción contencioso-administrativa, el Tribunal de Cuentas y los Delegados del Gobierno.'}},
{n:146, q:'La población de hecho de un municipio es:', o:{a:'Los vecinos inscritos en el Padrón.',b:'Las personas que residen habitualmente en el término municipal.',c:'Las personas que se encuentran en el municipio en el momento del censo.',d:'Son los mismos que los residentes.'}, correct:'a', why:{a:'Respuesta correcta según solucionario oficial Vol. I.'}},
{n:147, q:'El Pleno del Ayuntamiento aprueba el reglamento orgánico municipal con:', o:{a:'Mayoría simple.',b:'Mayoría absoluta.',c:'Mayoría de dos tercios.',d:'Unanimidad.'}, correct:'d', why:{d:'La LBRL establece que el Reglamento Orgánico Municipal, que regula la organización interna del Ayuntamiento, es aprobado por el Pleno con mayoría absoluta.'}},
{n:148, q:'El concejal que no asiste injustificadamente a más de tres sesiones consecutivas del Pleno:', o:{a:'Es automáticamente cesado.',b:'Puede ser objeto de expediente disciplinario.',c:'Pierde su condición de concejal.',d:'No hay consecuencia legalmente prevista.'}, correct:'a', why:{a:'La LOREG y la LBRL no establecen automáticamente el cese del concejal por inasistencia; sin embargo la normativa electoral prevé que la inasistencia reiterada e injustificada puede ser objeto de las medidas previstas en el Reglamento interno.'}},
{n:149, q:'¿Qué órgano autonómico valenciano tiene funciones equivalentes al Tribunal de Cuentas en el ámbito estatal?', o:{a:'El Síndic de Greuges.',b:'La Sindicatura de Comptes.',c:'El Consell Jurídic Consultiu.',d:'El Tribunal Superior de Justicia.'}, correct:'b', why:{b:'La Sindicatura de Comptes es el órgano fiscalizador supremo de la gestión económica, financiera y contable del sector público valenciano, equivalente al Tribunal de Cuentas en el ámbito estatal.'}},
{n:150, q:'Los Estatutos de Autonomía tienen carácter de:', o:{a:'Norma estatal con rango de ley orgánica.',b:'Norma autonómica con rango de ley.',c:'Norma constitucional.',d:'Norma administrativa.'}, correct:'b', why:{b:'Los Estatutos de Autonomía son leyes orgánicas del Estado (aprobadas por las Cortes Generales mediante el procedimiento de ley orgánica) y a la vez norma institucional básica de cada CCAA.'}},
{n:151, q:'Las Corporaciones Locales pueden sancionar las infracciones a sus Ordenanzas. La potestad sancionadora local:', o:{a:'Solo puede ser ejercida por el Alcalde.',b:'Es ejercida por los órganos locales conforme a los principios de la legislación básica del Estado.',c:'No existe, solo el Estado puede sancionar.',d:'Requiere siempre autorización judicial previa.'}, correct:'a', why:{a:'Las Entidades Locales ejercen la potestad sancionadora conforme a los principios establecidos en la legislación del Estado y de las CCAA, en el marco de sus competencias.'}},
{n:152, q:'El Padró Municipal d\'Habitants en la Comunitat Valenciana:', o:{a:'Es gestionado por la Generalitat.',b:'Es gestionado por cada Ayuntamiento, con la coordinación del INE.',c:'Es gestionado por la Diputación Provincial.',d:'Es gestionado por el Estado directamente.'}, correct:'b', why:{b:'El Padrón Municipal de Habitantes es gestionado por cada Ayuntamiento, bajo la coordinación del Instituto Nacional de Estadística (INE).'}},
{n:153, q:'La fusión de municipios en la Comunitat Valenciana requiere:', o:{a:'Solo acuerdo de los Plenos de los Ayuntamientos.',b:'Ley de Les Corts.',c:'Decreto del Consell.',d:'Aprobación de la Diputación Provincial.'}, correct:'c', why:{c:'La creación, supresión y alteración de los términos municipales, así como la fusión de municipios, se regula en la legislación autonómica valenciana, que exige audiencia de los municipios afectados y aprobación mediante Decreto del Consell.'}},
{n:154, q:'¿Cuántos concejales tiene como mínimo un Ayuntamiento en España?', o:{a:'3.',b:'5.',c:'7.',d:'9.'}, correct:'a', why:{a:'La LOREG establece que el número de Concejales varía según la población del municipio, siendo el mínimo de 5 Concejales para municipios de hasta 250 habitantes.'}},
{n:155, q:'El Consell Jurídic Consultiu de la Comunitat Valenciana emite dictámenes:', o:{a:'Solo preceptivos.',b:'Solo facultativos.',c:'Preceptivos y facultativos, según los casos.',d:'Siempre vinculantes.'}, correct:'d', why:{d:'El Consell Jurídic Consultiu emite dictámenes preceptivos (obligatorios) en los supuestos establecidos por ley y facultativos cuando se le consulta voluntariamente. Sus dictámenes, salvo excepción expresa, no son vinculantes.'}},
{n:156, q:'¿Cuál es el plazo para la aprobación del presupuesto municipal?', o:{a:'Antes del 1 de enero del ejercicio.',b:'Antes del 31 de diciembre del ejercicio anterior.',c:'En los primeros tres meses del ejercicio.',d:'No hay plazo fijo.'}, correct:'c', why:{c:'El presupuesto municipal debe ser aprobado por el Pleno antes del 31 de diciembre del año anterior al ejercicio a que se refiere, sin perjuicio de su prórroga automática si no se aprueba en plazo.'}},
{n:157, q:'¿Qué sucede si no se aprueba el presupuesto municipal antes del inicio del ejercicio?', o:{a:'Se suspende toda actividad municipal.',b:'Se prorroga automáticamente el del ejercicio anterior.',c:'El Estado asume la gestión.',d:'La Diputación aprueba un presupuesto provisional.'}, correct:'d', why:{d:'Si al inicio del ejercicio económico no se aprueba el presupuesto, se prorroga automáticamente el del ejercicio anterior, conforme al Texto Refundido de la Ley Reguladora de las Haciendas Locales.'}},
{n:158, q:'Las competencias delegadas de la CCAA a los municipios:', o:{a:'Se ejercen bajo la dirección y control de la CCAA.',b:'Pasan a ser propias del municipio.',c:'No necesitan financiación específica.',d:'Pueden ser ejercidas con total autonomía por el municipio.'}, correct:'d', why:{d:'Las competencias delegadas por la CCAA a los municipios se ejercen en los términos de la delegación, bajo la dirección y control de la Administración delegante, que puede dar instrucciones técnicas y revocar la delegación.'}},
];
